<section class="auth-page"><div class="auth-visual"><div class="auth-art-symbol">✦</div><h1>Find your people. Build your campus story.</h1><p>Join clubs, register for events, and make the most of university life.</p><div class="auth-caption">STUDENT-LED COMMUNITY</div></div><div class="auth-card-wrap"><div class="auth-card card"><div class="section-label">STUDENT SIGNUP</div><h2>Create account</h2><p>Use demonstration details for evaluation; do not enter real credentials on a shared demo.</p><form action="<?= e(url('register')) ?>" method="post" class="form-stack"><?= csrf_field() ?><label>Full name<input type="text" required name="full_name" maxlength="120" minlength="3" autocomplete="name" value="<?= e(old('full_name')) ?>"></label><label>Email<input required type="email" name="email" maxlength="190" autocomplete="email" value="<?= e(old('email')) ?>"></label><label>Student number<input type="text" required name="student_number" maxlength="50" value="<?= e(old('student_number')) ?>" placeholder="e.g. DEMO/2026/001"></label><label>Faculty<select required name="faculty"><option value="">Choose your faculty</option><?php foreach(array_slice(faculty_options(),0,3) as $faculty): ?><option value="<?= e($faculty) ?>" <?= old('faculty')===$faculty?'selected':'' ?>><?= e($faculty) ?></option><?php endforeach;?></select></label><label>Password <small>(10–72 characters)</small><input required type="password" minlength="10" maxlength="72" name="password" autocomplete="new-password"></label><label>Confirm password<input required type="password" minlength="10" maxlength="72" name="confirm_password" autocomplete="new-password"></label><button class="btn btn-primary btn-block" type="submit">Create my account →</button></form><p class="auth-link">Already registered? <a href="<?= e(url('login')) ?>">Sign in</a></p></div></div></section>
